import {test} from 'node:test';import assert from 'node:assert/strict';
import {storeProfileKey,emptyStoreProfile,cleanStoreProfile,loadStoreProfile,saveStoreProfile} from '../src/storeProfile.js';
const storage=()=>{const data=new Map();return {getItem:key=>data.get(key)||null,setItem:(key,value)=>data.set(key,value)}};
test('empty or damaged store profiles load safe defaults',()=>{const s=storage();assert.deepEqual(loadStoreProfile(s,'a'),{profile:emptyStoreProfile(),pendingCloud:false});s.setItem(storeProfileKey('a'),'bad');assert.deepEqual(loadStoreProfile(s,'a').profile,emptyStoreProfile());});
test('save/load round trip retains all four fields and account isolation',()=>{const s=storage(),p={storeName:'Sample Timber',ownerName:'Sample Owner',address:'Sample Road',mobile:'+91 00000 00000'};saveStoreProfile(s,'a',p,true);assert.deepEqual(loadStoreProfile(s,'a'),{profile:p,pendingCloud:true});assert.deepEqual(loadStoreProfile(s,'b').profile,emptyStoreProfile());saveStoreProfile(s,'a',p,false);assert.equal(loadStoreProfile(s,'a').pendingCloud,false);});
test('cleaning rejects nonstrings, strips unknown fields, caps lengths',()=>{assert.deepEqual(cleanStoreProfile({storeName:9,ownerName:null,mobile:{},address:'x',password:'bad'}),{storeName:'',ownerName:'',address:'x',mobile:''});assert.equal(cleanStoreProfile({address:'x'.repeat(700)}).address.length,500);});
test('storage failures do not claim success',()=>{const s={getItem:()=>{throw Error()},setItem:()=>{throw Error('Storage blocked')}};assert.deepEqual(loadStoreProfile(s,'a').profile,emptyStoreProfile());assert.throws(()=>saveStoreProfile(s,'a',emptyStoreProfile()),/Storage blocked/);});
